// userProfileCache.ts
export interface CacheStore<T> {
  get(key: string): Promise<T | undefined>;
  set(key: string, value: T, ttlMs: number): Promise<void>;
  delete(key: string): Promise<void>;
}

type Entry<T> = { value: T; expiresAt: number };

// In-process LRU with TTL. Swap for a Redis-backed CacheStore when running multiple instances.
export class MemoryStore<T> implements CacheStore<T> {
  private entries = new Map<string, Entry<T>>();

  constructor(private maxEntries = 10_000) {}

  async get(key: string): Promise<T | undefined> {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt <= Date.now()) {
      this.entries.delete(key);
      return undefined;
    }
    // Re-insert so Map order tracks recency.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  async set(key: string, value: T, ttlMs: number): Promise<void> {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: Date.now() + ttlMs });
    if (this.entries.size > this.maxEntries) {
      this.entries.delete(this.entries.keys().next().value!);
    }
  }

  async delete(key: string): Promise<void> {
    this.entries.delete(key);
  }
}

export class UserProfileCache<Profile> {
  private inFlight = new Map<string, Promise<Profile>>();

  constructor(
    private fetchProfile: (userId: string) => Promise<Profile>,
    private store: CacheStore<Profile> = new MemoryStore<Profile>(),
    private ttlMs = 60_000,
  ) {}

  async get(userId: string): Promise<Profile> {
    const key = this.key(userId);

    const cached = await this.store.get(key);
    if (cached !== undefined) return cached;

    // Concurrent misses share one upstream call.
    const pending = this.inFlight.get(key);
    if (pending) return pending;

    const request: Promise<Profile> = this.fetchProfile(userId)
      .then(async (profile) => {
        // Skip the write if invalidate() ran while the fetch was in flight.
        if (this.inFlight.get(key) === request) {
          await this.store.set(key, profile, this.ttlMs);
        }
        return profile;
      })
      .finally(() => {
        if (this.inFlight.get(key) === request) this.inFlight.delete(key);
      });

    this.inFlight.set(key, request);
    return request;
  }

  // Call after any profile write.
  async invalidate(userId: string): Promise<void> {
    const key = this.key(userId);
    this.inFlight.delete(key);
    await this.store.delete(key);
  }

  private key(userId: string): string {
    return `user-profile:${userId}`;
  }
}
